  type: 'product',
  multiple: true,
});

const selected = await resourcePicker({
  type: 'product',
  multiple: 5,
});

const selected = await resourcePicker({
  type: 'product',
  filter: {
    hidden: true,
    variants: false,
    draft: false,
    archived: false,
  },
});

const selected = await resourcePicker({
  type: 'product',
  filter: {
    query: 'Sweater',
  },
});

const selected = await resourcePicker({type: 'product'});

if (selected) {
  console.log(selected);
} else {
  console.log('Picker was cancelled by the user');
}

const selected = await resourcePicker({
  type: 'product',
  query: 'Sweater',
});

